// @name Colors
// @background #18181b
// @refresh 3600
// Tailwind's palette, picked by tapping. The classes are read when the frame
// draws, so `bg-${hue}-${shade}` works for every hue and shade.
const hues = ['red', 'orange', 'amber', 'yellow', 'lime', 'green', 'emerald', 'teal', 'cyan',
  'sky', 'blue', 'indigo', 'violet', 'purple', 'fuchsia', 'pink', 'rose', 'stone']
const shades = [50, 100, 200, 300, 400, 500, 600, 700, 800, 900, 950]

// The picked color, and a flag per swatch for the one picked. They are
// signals: a tap runs only the card and the swatches that read them, not get().
const hue = signal('sky')
const shade = signal(500)
const hueOn = Object.fromEntries(hues.map((h) => [h, signal(false)]))
const shadeOn = Object.fromEntries(shades.map((s) => [s, signal(false)]))
const show = (h, s) => {
  hue.value = h
  shade.value = s
  for (const x of hues) hueOn[x].value = x === h
  for (const x of shades) shadeOn[x].value = x === s
}

// The picked color outlives the render: a board may start each render with a
// fresh module, and a frame rendered on its server does, at every tap.
let recalled = false
const recallPick = () => {
  if (recalled) return
  recalled = true
  const kept = frameos.recall('pick')
  if (kept) show(kept.hue, kept.shade)
  else show(hue.peek(), shade.peek())
}
const pick = (next) => {
  show(next.hue || hue.peek(), next.shade || shade.peek())
  frameos.remember('pick', { hue: hue.peek(), shade: shade.peek() })
}

// High contrast where the panel shows no color (black and white, greys), or
// when the scene's Contrast setting asks for it.
const highContrast = (app) => {
  const mode = app.state.contrast || 'auto'
  return mode === 'high' || (mode === 'auto' && app.frame.color === false)
}
// The look: colors, colors with high contrast, or, on a panel that shows no
// color, no fills at all (a shade there is a grey that dithers to dots and
// looks like its neighbours): every swatch white with its name, the picked
// one black.
const themeOf = (app) => (!highContrast(app) ? THEMES.color : app.frame.color === false ? THEMES.mono : THEMES.high)
// A swatch's fill: its color, or white (black when picked) without color.
const fill = (t, cls, on) => (t.mono ? (on ? 'bg-black' : 'bg-white') : cls)

// The swatches keep their colors in high contrast: their outlines, the
// picked one's mark and the label go black and white, and each swatch is
// named (its hue, its shade), as a panel without color shows them as greys
// that look alike.
const THEMES = {
  color: {
    page: 'bg-zinc-900 text-white',
    card: 'p-5',
    cardSmall: 'p-3',
    hint: 'opacity-70',
    chip: '',
    swatch: '',
    picked: 'border-4 border-white',
    press: 'active:border-4 active:border-white/50',
    mark: false,
  },
  high: {
    page: 'bg-white text-black',
    card: 'p-[18px] border-2 border-black',
    cardSmall: 'p-[10px] border-2 border-black',
    hint: '',
    chip: 'self-start flex flex-col px-3 py-1 rounded-xl bg-white text-black border-2 border-black',
    swatch: 'flex items-center justify-center border-2 border-black',
    picked: 'flex items-center justify-center border-4 border-black',
    press: '',
    mark: true,
  },
}
THEMES.mono = { ...THEMES.high, chip: '', mono: true }

// The picked swatch's mark on a round panel in high contrast: a white dot
// ringed in black, seen on any shade.
const Dot = () => <div className="w-4 h-4 rounded-full bg-white border-2 border-black" />

// A swatch's name in high contrast, on white (the picked one's on black),
// read on any shade; `size` its text in px (a hue's name, a shade's number).
let nameSize = 12
let numberSize = 12
const Mark = ({ text, on, size }) => (
  <div className={`px-[3px] rounded-md text-[${size || nameSize}px] leading-tight font-semibold whitespace-nowrap ${on ? 'bg-black text-white' : 'bg-white text-black'}`}>{text}</div>
)

// The picked color, large, with its class name; `h` px tall on a small screen.
const Card = memo(({ t, h }) => {
  const ink = shade.value < 400 ? 'text-black/80' : 'text-white'
  const label = [
    <span className={`${h ? 'text-xs' : 'text-sm'} uppercase font-semibold ${t.hint}`}>Pick a color</span>,
    <span className={`${h ? 'text-xl' : 'text-3xl'} font-mono`}>{`bg-${hue.value}-${shade.value}`}</span>,
  ]
  return (
    <div className={`flex flex-col justify-end ${h ? `h-[${h}px] rounded-2xl ${t.cardSmall}` : `h-36 rounded-3xl ${t.card}`} ${fill(t, `bg-${hue.value}-${shade.value}`, false)} ${t.chip || t.mono ? '' : ink}`}>
      {t.chip ? <div className={t.chip}>{label}</div> : label}
    </div>
  )
})

// A shade of the picked hue.
const ShadeSwatch = memo(({ s, t }) => {
  const on = shadeOn[s].value
  return (
    <div className={`flex-1 rounded-lg ${fill(t, `bg-${hue.value}-${s}`, on)} ${on ? t.picked : t.swatch}`}
      onClick={() => pick({ shade: s })}>
      {t.mark ? <Mark text={String(s)} on={on} size={numberSize} /> : null}
    </div>
  )
})

const HueSwatch = memo(({ h, t }) => {
  const on = hueOn[h].value
  return (
    <div className={`rounded-xl ${fill(t, `bg-${h}-500`, on)} ${on ? t.picked : `${t.swatch} ${t.press}`}`}
      onClick={() => pick({ hue: h })}>
      {t.mark ? <Mark text={h} on={on} /> : null}
    </div>
  )
})

// On a round panel: a color wheel. The hues around the rim, the picked hue's
// shades in a ring inside them, the picked color as a disc in the middle.
const RoundCard = memo(({ t, d, x, y, px }) => {
  const ink = shade.value < 400 ? 'text-black/80' : 'text-white'
  const label = [
    <span className={`text-[${px(14)}px] uppercase font-semibold ${t.hint}`}>Pick a color</span>,
    <span className={`text-[${px(24)}px] font-mono`}>{`bg-${hue.value}-${shade.value}`}</span>,
  ]
  return (
    <div className={`absolute left-[${x}px] top-[${y}px] w-[${d}px] h-[${d}px] flex flex-col items-center justify-center rounded-full ${t.chip || t.mono ? 'border-2 border-black' : ''} ${fill(t, `bg-${hue.value}-${shade.value}`, false)} ${t.chip || t.mono ? '' : ink}`}>
      {t.chip ? <div className="flex flex-col items-center px-3 py-1 rounded-xl bg-white text-black border-2 border-black">{label}</div> : label}
    </div>
  )
})
const RoundShade = memo(({ s, t, d, x, y }) => {
  const on = shadeOn[s].value
  return (
    <div className={`absolute left-[${x}px] top-[${y}px] w-[${d}px] h-[${d}px] rounded-full ${fill(t, `bg-${hue.value}-${s}`, on)} ${on ? t.picked : t.swatch}`}
      onClick={() => pick({ shade: s })}>
      {t.mark && on ? <Dot /> : null}
    </div>
  )
})
const RoundHue = memo(({ h, t, d, x, y }) => {
  const on = hueOn[h].value
  return (
    <div className={`absolute left-[${x}px] top-[${y}px] w-[${d}px] h-[${d}px] rounded-full ${fill(t, `bg-${h}-500`, on)} ${on ? t.picked : `${t.swatch} ${t.press}`}`}
      onClick={() => pick({ hue: h })}>
      {t.mark && on ? <Dot /> : null}
    </div>
  )
})
const getRound = (context, t) => {
  const W = context.imageWidth, H = context.imageHeight
  const size = Math.min(W, H), r = size / 2
  const k = r / 240
  const px = (n) => Math.max(14, Math.round(n * k))
  const around = (list, ring, d, i) => {
    const a = (i / list.length) * 2 * Math.PI
    return { d, x: Math.round(r + ring * Math.sin(a) - d / 2), y: Math.round(r - ring * Math.cos(a) - d / 2) }
  }
  const hueD = Math.round(r * 0.22)
  const hueRing = r - Math.max(12, Math.round(12 * k)) - hueD / 2
  const shadeD = Math.round(r * 0.18)
  const shadeRing = hueRing - hueD / 2 - Math.round(10 * k) - shadeD / 2
  const card = Math.round(2 * (shadeRing - shadeD / 2 - Math.round(12 * k)))
  return (
    <div className={`relative w-[${W}px] h-[${H}px] ${t.page}`}>
      <div className={`absolute left-[${(W - size) >> 1}px] top-[${(H - size) >> 1}px] w-[${size}px] h-[${size}px]`}>
        <RoundCard t={t} px={px} d={card} x={Math.round(r - card / 2)} y={Math.round(r - card / 2)} />
        {shades.map((s, i) => <RoundShade s={s} t={t} {...around(shades, shadeRing, shadeD, i)} />)}
        {hues.map((h, i) => <RoundHue h={h} t={t} {...around(hues, hueRing, hueD, i)} />)}
      </div>
    </div>
  )
}

export function get(app, context) {
  recallPick()
  if (context?.round === true) return getRound(context, themeOf(app))
  const t = themeOf(app)
  // A short or narrow screen (a watch, a 2.8" panel, a strip): a smaller card
  // and shades, and the hues in two rows where it is wider than tall (and,
  // with their names on them, wide enough for the names). At full
  // size the card and the shades take 250 px of the height.
  const W = context?.imageWidth ?? app.frame.width
  const H = context?.imageHeight ?? app.frame.height
  const small = W < 380 || H < 400
  const card = small ? Math.max(56, Math.min(144, Math.round(H * 0.28))) : 0
  const wideHues = small && W >= H * 1.3 && (W >= 600 || !t.mark)
  // The names as big as their swatches let them be ("fuchsia", "950").
  const pad = small ? 12 : 20, gap = small ? 6 : 8
  const hueW = (W - 2 * pad - (wideHues ? 8 : 5) * gap) / (wideHues ? 9 : 6)
  const shadeW = (W - 2 * pad - 10 * 4) / 11
  nameSize = Math.max(10, Math.min(small ? 14 : 16, Math.floor((hueW - 10) / 4.2)))
  numberSize = Math.max(10, Math.min(small ? 14 : 16, Math.floor((shadeW - 10) / 1.9)))
  return (
    <div className={`flex flex-col ${small ? 'gap-2 p-3' : 'gap-3 p-5'} ${t.page}`}>
      <Card t={t} h={card} />
      <div className={`flex gap-1 ${small ? 'h-8' : 'h-12'}`}>
        {shades.map((s) => <ShadeSwatch s={s} t={t} />)}
      </div>
      <div className={`flex-1 grid ${wideHues ? 'grid-cols-9 gap-[6px]' : small ? 'grid-cols-6 gap-[6px]' : 'grid-cols-6 gap-2'}`}>
        {hues.map((h) => <HueSwatch h={h} t={t} />)}
      </div>
    </div>
  )
}
